COMMENT ON TABLE public.platform_roles IS '[A. Identité et utilisateurs] Rôles plateforme (PILOTE, SUPPORT…).';
COMMENT ON TABLE public.tenant_roles IS '[A. Identité et utilisateurs] Rôles tenant (système si tenant_id null).';
